  const errors: string[] = [];

  let store;
  try {
    store = openRunStore({ stateRoot: input.stateRoot });
  } catch (error) {
    errors.push(
      `failed to open run store at ${input.stateRoot}: ${errorMessage(error)}`
    );
    return Promise.resolve({ ok: false, errors });
  }

